import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;

/**
 * Caches the received thumbnail image.
 * @param fileInfo the information about the file
 * @param inputStream the input stream containing the thumbnail image data
 * @throws IOException if an I/O error occurs
 */
public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
    if (fileInfo == null || inputStream == null) {
        return;
    }

    // Convert the InputStream to a byte array
    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    byte[] buffer = new byte[1024];
    int length;
    while ((length = inputStream.read(buffer)) != -1) {
        byteArrayOutputStream.write(buffer, 0, length);
    }
    byte[] thumbnailData = byteArrayOutputStream.toByteArray();
    byteArrayOutputStream.close();

    // Create a hash of the thumbnail data
    int hash = Arrays.hashCode(thumbnailData);

    // Use a HashMap to check for duplicates
    static final HashMap<Integer, BaseFileInfo> thumbnailCache = new HashMap<>();

    // Check if the thumbnail is already cached
    if (thumbnailCache.containsKey(hash)) {
        System.out.println("Duplicate thumbnail detected for file: " + fileInfo.getName());
        return;
    }

    // Cache the thumbnail data
    thumbnailCache.put(hash, fileInfo);

    // Optionally, log or process the cached thumbnail data
    System.out.println("Thumbnail cached for file: " + fileInfo.getName());
}
```

