// Function to generate all substrings of a given string
func allSubstrings(_ inputString: String) -> [String] {
    let length = inputString.count
    var substrings = [String]()
    for i in 0..<length {
        for j in (i + 1)...length {
            substrings.append(String(inputString[i..<j]))
        }
    }
    return substrings
}

// Function to find the longest substring that appears at least k times in the list of strings
func longestSubstring(strings: [String], k: Int) -> String? {
    guard !strings.isEmpty else {
        return nil
    }

    var longestStr = ""
    for s in strings {
        for substr in allSubstrings(s) {
            let count = strings.filter { substr.contains($0) }.count
            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }
    return longestStr.isEmpty ? nil : longestStr
}
